// MergeScmEvent fills zero-valued fields in dst from src.
func MergeScmEvent(dst, src *ScmEvent) {
	if dst.Email == "" {
		dst.Email = src.Email
	}
	if dst.EventId == "" {
		dst.EventId = src.EventId
	}
	if dst.TimestampMs == 0 {
		dst.TimestampMs = src.TimestampMs
	}
	if dst.Provider == 0 {
		dst.Provider = src.Provider
	}
	if dst.ApiEndpoint == "" {
		dst.ApiEndpoint = src.ApiEndpoint
	}
	if dst.Operation == 0 {
		dst.Operation = src.Operation
	}
	if dst.Owner == "" {
		dst.Owner = src.Owner
	}
	if dst.Repo == "" {
		dst.Repo = src.Repo
	}
	if dst.RepoKey == "" {
		dst.RepoKey = src.RepoKey
	}
	if dst.ResourceId == "" {
		dst.ResourceId = src.ResourceId
	}
	if !dst.Succeeded {
		dst.Succeeded = src.Succeeded
	}
	if dst.StatusCode == 0 {
		dst.StatusCode = src.StatusCode
	}
	if dst.ErrorMessage == "" {
		dst.ErrorMessage = src.ErrorMessage
	}
	if dst.LatencyMs == 0 {
		dst.LatencyMs = src.LatencyMs
	}
	if dst.RateLimitRemaining == 0 {
		dst.RateLimitRemaining = src.RateLimitRemaining
	}
	if dst.RateLimitLimit == 0 {
		dst.RateLimitLimit = src.RateLimitLimit
	}
	if dst.RateLimitResetAt == 0 {
		dst.RateLimitResetAt = src.RateLimitResetAt
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

